CREATE TABLE makeup_links(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,original_participant_id TEXT NOT NULL,target_participant_id TEXT NOT NULL,target_lesson_id TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,original_participant_id) REFERENCES lesson_participants(tenant_id,id),FOREIGN KEY(tenant_id,target_participant_id) REFERENCES lesson_participants(tenant_id,id),FOREIGN KEY(tenant_id,target_lesson_id) REFERENCES lessons(tenant_id,id));
